<?php
declare(strict_types=1);
namespace HardnessMcp\Tools\Finance;
use DateTimeImmutable; use InvalidArgumentException;
final class FinanceSummaryInput {
    private string $dateFrom; private string $dateTo; private string $dateBasis; private string $view; private ?array $cursor; private string $groupBy; private string $status; private ?int $partnerId; private ?int $carrierId; private int $limit;
    /** @param array<string,mixed> $arguments */ public static function fromArguments(array $arguments): self { $input=new self(); $input->dateFrom=(string)$arguments['date_from']; $input->dateTo=(string)$arguments['date_to']; $input->dateBasis=isset($arguments['date_basis'])?(string)$arguments['date_basis']:'due_date'; $input->view=isset($arguments['view'])?(string)$arguments['view']:'summary'; $input->cursor=isset($arguments['cursor'])?FinanceTitleCursor::decode((string)$arguments['cursor']):null; $input->groupBy=(string)$arguments['group_by']; $input->status=isset($arguments['status'])?(string)$arguments['status']:'all'; $input->partnerId=isset($arguments['partner_id'])?(int)$arguments['partner_id']:null; $input->carrierId=isset($arguments['carrier_id'])?(int)$arguments['carrier_id']:null; $input->limit=isset($arguments['limit'])?(int)$arguments['limit']:20; $input->assertPeriod(); return $input; }
    public function getDateFrom(): string{return $this->dateFrom;} public function getDateTo(): string{return $this->dateTo;} public function getDateBasis(): string{return $this->dateBasis;} public function getView(): string{return $this->view;} /** @return array{due_date:string,title_id:int}|null */ public function getCursor(): ?array{return $this->cursor;} public function getGroupBy(): string{return $this->groupBy;} public function getStatus(): string{return $this->status;} public function getPartnerId(): ?int{return $this->partnerId;} public function getCarrierId(): ?int{return $this->carrierId;} public function getLimit(): int{return $this->limit;}
    private function assertPeriod(): void { $from=self::date($this->dateFrom);$to=self::date($this->dateTo);if($from>$to)throw new InvalidArgumentException('A data inicial não pode ser posterior à data final.');$days=(int)$from->diff($to)->format('%a')+1;if($days>366)throw new InvalidArgumentException('Relatórios interativos aceitam no máximo 12 meses. Não divida um período maior em consultas sequenciais; peça ao usuário um único recorte de até 12 meses.');if($this->groupBy==='day'&&$days>90)throw new InvalidArgumentException('O agrupamento diário aceita no máximo 90 dias.'); }
    private static function date(string $value): DateTimeImmutable { $date=DateTimeImmutable::createFromFormat('!Y-m-d',$value);$errors=DateTimeImmutable::getLastErrors();if($date===false||(is_array($errors)&&($errors['warning_count']>0||$errors['error_count']>0)))throw new InvalidArgumentException('Informe datas válidas no formato AAAA-MM-DD.');return $date; }
}
